describe('Create New Task Form', () => {
  beforeEach(() => {
    cy.visit('/tasks/new');
  });

  it('should successfully create a new task by filling out the form and clicking Save', () => {
    // Verify form is visible
    cy.get('[data-testid="task-form"]').should('be.visible');
    cy.get('[data-testid="task-title-input"]').should('be.visible');
    cy.get('[data-testid="task-description-textarea"]').should('be.visible');
    cy.get('[data-testid="task-priority-select"]').should('be.visible');
    cy.get('[data-testid="save-task-button"]').should('be.visible');

    // Fill in form fields
    cy.get('[data-testid="task-title-input"]').type('Complete Cypress Test Script');
    cy.get('[data-testid="task-description-textarea"]').type('This task involves creating a Cypress test script for a new task form.');
    cy.get('[data-testid="task-priority-select"]').select('High');

    // Click Save button
    cy.get('[data-testid="save-task-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Task created successfully');

    // Verify task is redirected to task list
    cy.url().should('include', '/tasks');

    // Verify task appears in list
    cy.get('[data-testid="task-list"]').should('be.visible');
    cy.get('[data-testid="task-item"]').should('contain', 'Complete Cypress Test Script');
    cy.get('[data-testid="task-item"]').should('contain', 'High');
  });

  it('should display validation errors when required fields are left empty', () => {
    // Verify form is visible
    cy.get('[data-testid="task-form"]').should('be.visible');

    // Attempt to submit without filling any fields
    cy.get('[data-testid="save-task-button"]').click();

    // Verify validation error messages appear
    cy.get('[data-testid="validation-error-title"]').should('be.visible');
    cy.get('[data-testid="validation-error-title"]').should('contain', 'Task title is required');
    cy.get('[data-testid="validation-error-description"]').should('be.visible');
    cy.get('[data-testid="validation-error-description"]').should('contain', 'Task description cannot be empty');

    // Verify form is still on the new task page
    cy.url().should('include', '/tasks/new');

    // Verify save button is still enabled (or disabled if validation prevents submission)
    cy.get('[data-testid="save-task-button"]').should('be.visible');
    cy.get('[data-testid="save-task-button"]').should('not.be.disabled');

    // Fill only title and submit to test description validation
    cy.get('[data-testid="task-title-input"]').type('Test with missing description');
    cy.get('[data-testid="save-task-button"]').click();

    // Verify description error persists
    cy.get('[data-testid="validation-error-description"]').should('be.visible');
    cy.get('[data-testid="validation-error-description"]').should('contain', 'Task description cannot be empty');
  });
});
